// Hand-written animated icons. Re-exported from the package root (src/index.ts is generated by scripts/build.mjs).
// They use the same grid and props as the line set, and stop moving under
// prefers-reduced-motion: the spinner becomes the static `loader` arc, and the
// streaming dots hold still.
import * as React from "react";

import type { ChatPRDIconProps } from "./runtime.js";

// Keyframes are injected once into document.head rather than rendered inside each SVG.
// A <style> element inside the icon would leak its CSS into the textContent of every
// ancestor (status regions, buttons, test queries), so the components keep their
// markup to shapes only and need no global stylesheet from the app.
const SPINNER_CSS = `
@keyframes chatprd-spin { to { transform: rotate(360deg); } }
.chatprd-spinner-arc { transform-origin: 12px 12px; animation: chatprd-spin 0.9s linear infinite; }
@media (prefers-reduced-motion: reduce) { .chatprd-spinner-arc { animation: none; } }
`;

const DOTS_CSS = `
@keyframes chatprd-dot { 0%, 80%, 100% { opacity: 0.25; } 40% { opacity: 1; } }
.chatprd-dots circle { animation: chatprd-dot 1.2s ease-in-out infinite; }
.chatprd-dots circle:nth-of-type(2) { animation-delay: 0.15s; }
.chatprd-dots circle:nth-of-type(3) { animation-delay: 0.3s; }
@media (prefers-reduced-motion: reduce) { .chatprd-dots circle { animation: none; opacity: 1; } }
`;

function useGlobalStyle(id: string, css: string) {
  React.useInsertionEffect(() => {
    if (typeof document === "undefined" || document.getElementById(id)) return;
    const style = document.createElement("style");
    style.id = id;
    style.textContent = css;
    document.head.appendChild(style);
  }, [id, css]);
}

function useA11y(title?: string) {
  const titleId = React.useId();
  const attrs: React.SVGProps<SVGSVGElement> = title
    ? { role: "img", "aria-labelledby": titleId }
    : { "aria-hidden": true };
  return { titleId, attrs };
}

/**
 * Animated loading spinner: a faint full ring with a rotating 3/4 arc.
 * Use for anything in flight (saving, generating, uploading). For a static
 * "loading" glyph, e.g. in a status legend, use `IconLoader`.
 */
export const IconSpinner = React.forwardRef<SVGSVGElement, ChatPRDIconProps>(function IconSpinner(
  { size = 24, strokeWidth = 1.75, absoluteStrokeWidth, title, className, ...rest },
  ref,
) {
  const { titleId, attrs } = useA11y(title ?? undefined);
  useGlobalStyle("chatprd-icons-spinner", SPINNER_CSS);
  const sw = absoluteStrokeWidth && typeof size === "number" ? (Number(strokeWidth) * 24) / size : strokeWidth;
  return (
    <svg
      ref={ref}
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={sw}
      strokeLinecap="round"
      strokeLinejoin="round"
      focusable="false"
      className={["chatprd-icon", "chatprd-icon-spinner", className].filter(Boolean).join(" ")}
      {...attrs}
      {...rest}
    >
      {title ? <title id={titleId}>{title}</title> : null}
      <circle cx="12" cy="12" r="8.5" opacity="0.2" />
      <path className="chatprd-spinner-arc" d="M20.5 12A8.5 8.5 0 1 1 12 3.5" />
    </svg>
  );
});

/**
 * Animated "streaming" indicator: three dots that pulse in turn, for a
 * response that is being generated. The static version is `IconStreaming`.
 */
export const IconStreamingDots = React.forwardRef<SVGSVGElement, ChatPRDIconProps>(function IconStreamingDots(
  { size = 24, title, className, strokeWidth: _strokeWidth, absoluteStrokeWidth: _abs, ...rest },
  ref,
) {
  const { titleId, attrs } = useA11y(title ?? undefined);
  useGlobalStyle("chatprd-icons-streaming-dots", DOTS_CSS);
  return (
    <svg
      ref={ref}
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="currentColor"
      focusable="false"
      className={["chatprd-icon", "chatprd-icon-streaming-dots", "chatprd-dots", className].filter(Boolean).join(" ")}
      {...attrs}
      {...rest}
    >
      {title ? <title id={titleId}>{title}</title> : null}
      <circle cx="6" cy="12" r="2" />
      <circle cx="12" cy="12" r="2" />
      <circle cx="18" cy="12" r="2" />
    </svg>
  );
});
